// The Octa Pass core for the Android app and its autofill and credential providers: the Kotlin
// bindings (src/main/kotlin, generated by crates/octapass-ffi/scripts/build-android.sh) over
// liboctapass_ffi.so (jniLibs/). On Android, use `net.java.dev.jna:jna:<version>@aar` instead
// of the plain JNA jar.
//
// The tests run on the JVM against a host build of the library with the in-process TestServer:
// crates/octapass-ffi/scripts/test-kotlin.sh passes it as -PoctapassFfiTesting=<dir>, with the
// matching bindings in <dir>/kotlin and the library in <dir>/lib.
plugins {
    kotlin("jvm") version "2.3.20"
}

group = "app.octap"
version = "0.1.0"

val testing: String? = providers.gradleProperty("octapassFfiTesting").orNull
if (testing != null) {
    // Its own build directory, so switching flavours never mixes incremental compiler state.
    layout.buildDirectory = layout.projectDirectory.dir("build/testing")
}

kotlin {
    jvmToolchain(17)
    if (testing != null) {
        sourceSets.main { kotlin.setSrcDirs(listOf("$testing/kotlin")) }
    }
}

dependencies {
    implementation("net.java.dev.jna:jna:5.19.1")
    testImplementation(kotlin("test"))
}

tasks.test {
    useJUnitPlatform()
    onlyIf("needs the test flavour of the library (scripts/test-kotlin.sh)") { testing != null }
    systemProperty("jna.library.path", "$testing/lib")
    testLogging { events("passed", "failed") }
}
